    def inb(x, y):
        return 0 <= x < w and 0 <= y < h

    def bfs_dist(start, goal):
        if start == goal:
            return 0
        if goal in obstacles:
            return 10**9
        sx0, sy0 = start
        if (sx0, sy0) in obstacles:
            return 10**9
        qx, qy = [sx0], [sy0]
        dist = {(sx0, sy0): 0}
        qi = 0
        while qi < len(qx):
            x, y = qx[qi], qy[qi]
            qi += 1
            d = dist[(x, y)]
            for dx, dy in moves:
                nx, ny = x + dx, y + dy
                if not inb(nx, ny) or (nx, ny) in obstacles:
                    continue
                if (nx, ny) not in dist:
                    nd = d + 1
                    if (nx, ny) == goal:
                        return nd
                    dist[(nx, ny)] = nd
                    qx.append(nx)
                    qy.append(ny)
        return 10**9

    def best_move():
        if not resources:
            tx, ty = (w - 1) // 2, (h - 1) // 2
            best = (10**9, 10**9)
            bestm = (0, 0)
            for dx, dy in moves:
                nx, ny = sx + dx, sy + dy
                if not inb(nx, ny) or (nx, ny) in obstacles:
                    continue
                v = (abs(nx - tx) + abs(ny - ty), abs(nx - ox) + abs(ny - oy))
